<?php declare( strict_types=1 ); namespace Amanah\SEOEngine\AI; defined( 'ABSPATH' ) || exit; final class AIResponse { private $provider; private $model; private $content; private $usage; private $raw; public function __construct(string $provider,string $model,string $content,array $usage=array(),array $raw=array()){$this->provider=$provider;$this->model=$model;$this->content=$content;$this->usage=$usage;$this->raw=$raw;} public function getProvider(): string{return $this->provider;} public function getModel(): string{return $this->model;} public function getContent(): string{return $this->content;} public function getUsage(): array{return $this->usage;} public function getRaw(): array{return $this->raw;} }